using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ScoreXPItemData", menuName = "Data/ScoreXP/ScoreXPItemData", order = 0)]
public class ScoreXPItemData : ScriptableObject
{
	[SerializeField]
	private string scoreXPItemLocalizationID;

	[SerializeField]
	private int scoreXPItemValue;

	[SerializeField]
	private int priorityOnScoreXPList;

	[SerializeField]
	private bool disableScoreXPItemTextAmountIfOnlyOne;

	public int PriorityOnScoreXPList => priorityOnScoreXPList;

	public string GetScoreXPItemLocalizedName(int amount)
	{
		string text = "";
		if (disableScoreXPItemTextAmountIfOnlyOne)
		{
			if (amount > 1)
			{
				text = $"({amount})";
			}
		}
		else
		{
			text = $"({amount})";
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(scoreXPItemLocalizationID) + " " + text;
	}

	public virtual int GetScoreXPItemValue()
	{
		return scoreXPItemValue;
	}
}
